  "Facturación mensual automatizada.": { gl: "Facturación mensual automatizada.", ca: "Facturació mensual automatitzada.", en: "Automated monthly invoicing." },
  "Gestión trimestral sin trabajo adicional.": { gl: "Xestión trimestral sen traballo adicional.", ca: "Gestió trimestral sense feina addicional.", en: "Quarterly management without extra work." },
  "Ver demo": { gl: "Ver demo", ca: "Veure la demo", en: "See demo" },
  "Quiero saber más": { gl: "Quero saber máis", ca: "Vull saber-ne més", en: "Learn more" },
  "Facturación sencilla.": { gl: "Facturación sinxela.", ca: "Facturació senzilla.", en: "Simple invoicing." },
  "Del cobro al envío.": { gl: "Do cobro ao envío.", ca: "Del cobrament a l'enviament.", en: "From payment to submission." },
  "Convierte los cobros identificados de Bizum o transferencia en borradores de factura, revísalos y envía facturas ordinarias o rectificativas a la Agencia Tributaria desde una sola aplicación.": { gl: "Converte os cobros identificados de Bizum ou transferencia en borradores de factura, revísaos e envía facturas ordinarias ou rectificativas á Axencia Tributaria desde unha única aplicación.", ca: "Converteix els cobraments identificats de Bizum o transferència en esborranys de factura, revisa'ls i envia factures ordinàries o rectificatives a l'Agència Tributària des d'una sola aplicació.", en: "Turn identified Bizum payments or bank transfers into invoice drafts, review them, and submit standard or corrective invoices to the Tax Agency from a single application." },
  "Descubrir cómo funciona": { gl: "Descubrir como funciona", ca: "Descobrir com funciona", en: "See how it works" },
  "Ver la aplicación": { gl: "Ver a aplicación", ca: "Veure l'aplicació", en: "See the application" },
  "Cobros convertidos en borradores": { gl: "Cobros convertidos en borradores", ca: "Cobraments convertits en esborranys", en: "Payments turned into drafts" },
  "PDF sin Word": { gl: "PDF sen Word", ca: "PDF sense Word", en: "PDF without Word" },
  "Datos en tu equipo": { gl: "Datos no teu equipo", ca: "Dades al teu equip", en: "Data on your computer" },
